SEARCH, PICK, CLASS, DAY, READ, CMP = ("search in a given timetable, notice or log", "commonsense selection",
                                       "classification of a given list", "day of the week",
                                       "reading a given text, multiple choice", "comparison of given offers")
NO = rx(r"(?i)(^|\W)ні(\W|$)|не встиг|не змож|не вийде|не можна|неможливо")
ONLY = " Назви лише потрібне через кому."


def mc(text, question, options, answer):
    letters = "АБВГ"
    body = "\n".join(f"{letters[i]}) {o}" for i, o in enumerate(options))
    return f"Прочитай текст і дай відповідь літерою.\nТекст: «{text}»\nПитання: {question}\n{body}", answer


